// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        uint256 ownerBalBefore = c.balanceOf(address(this));

        vm.deal(actor, 1 ether);

        vm.prank(actor);
        bool ok;
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 callerBal = c.balanceOf(actor);
        uint256 totalDist = c.totalDistributed();

        assertTrue(callerBal != totalDist);
    }
}
